      "lines": [
        {
          "role": "A",
          "text": "السَّلَام، عَنْدِكُم رَنْدِيفُو؟",
          "fr": "Bonjour, vous avez rendez-vous ?"
        },
        {
          "role": "B",
          "text": "إِي، عَنْدِي كُولُونْ فِي 10",
          "fr": "Oui, j’ai un entretien à 10h."
        },
        {
          "role": "A",
          "text": "قْعُدُوا، المَسْؤُول يْجِي",
          "fr": "Asseyez-vous, le responsable arrive."
        },
        {
          "role": "B",
          "text": "حَدِّثْنِي عَلَى خِبْرَتَك",
          "fr": "Parlez-moi de votre expérience."
        },
        {
          "role": "A",
          "text": "خْدَمْت ثَلَاث سْنِين فِي التِّجَارَة",
          "fr": "J’ai travaillé trois ans dans le commerce."
        },
        {
          "role": "B",
          "text": "عْلَاش بَغِيت تْخْلَع مِن الخِدْمَة؟",
          "fr": "Pourquoi voulez-vous quitter votre poste ?"
        },
        {
          "role": "A",
          "text": "نْقَعْد فُرَص جْدَاد",
          "fr": "Je cherche de nouvelles opportunités."
        },
        {
          "role": "B",
          "text": "مَتَى تْقْدَر تْبْدَأ؟",
          "fr": "Quand pouvez-vous commencer ?"
        },
        {
          "role": "A",
          "text": "مِن الأُسْبُوع الجَاي إِنْ شَاء اللَّه",
          "fr": "Dès la semaine prochaine si possible."
        },
        {
          "role": "B",
          "text": "شُكْرًا، نْعَاوَدُو نْتَصِلُوا بِيك",
          "fr": "Merci, on vous recontacte."
        }
      ]
